function redAct(r,action,value){const no=message=>({ok:false,message});if(action==='accept'){if(r.status!=='accepted')Object.assign(r,redInitial(),{status:'accepted'});return {ok:true};}if(action==='decline'){Object.assign(r,redInitial(),{status:'declined'});return {ok:true,message:'ยังไม่รับงาน ไม่มีการทดสอบเริ่มขึ้น'};}if(r.status!=='accepted')return no('รับงานลูกค้าก่อนเริ่มขั้นตอนนี้');if(action==='question'&&['assets','time','rules'].includes(value)){if(!r.questions.includes(value))r.questions.push(value);return {ok:true};}if(action==='scope'){if(r.questions.length!==3)return no('ถามทรัพย์สิน เวลา และข้อห้ามให้ครบก่อน');r.scope=true;return {ok:true};}if(!r.scope)return no('ยังไม่ได้ยืนยันขอบเขตงาน');if(action==='request'){if(!['INV-104','INV-105'].includes(value))return no('อยู่นอกขอบเขตระบบจำลอง');if(value==='INV-105'){if(r.fixed){r.retested=true;return {ok:true,code:403,message:'403 Forbidden — ระบบตรวจเจ้าของเอกสารแล้ว'};}r.viewed=true;return {ok:true,code:200,message:'200 OK — อ่านใบแจ้งหนี้ของแผนกอื่นได้โดยไม่ควรมีสิทธิ์'};}return {ok:true,code:200,message:'200 OK — เอกสารของบัญชีทดสอบที่มีสิทธิ์'};}if(action==='evidence'){if(!r.viewed)return no('ทดลองอ่านเอกสารข้ามบัญชีก่อน');r.evidence=true;return {ok:true};}if(action==='fix'){if(!r.evidence)return no('เก็บหลักฐานก่อนจำลองการแก้ไข');r.fixed=true;return {ok:true};}if(action==='report'){if(!r.evidence||!r.retested)return no('เก็บหลักฐานและทดสอบซ้ำหลังแก้ไขก่อน');if(!['medium','high','critical'].includes(value?.severity)||clampText(value?.impact).trim().length<15||clampText(value?.fix).trim().length<15)return no('เลือกระดับความรุนแรง และเขียนผลกระทบกับวิธีแก้อย่างละอย่างน้อย 15 ตัวอักษร');r.report={severity:value.severity,impact:clampText(value.impact),fix:clampText(value.fix)};r.submitted=true;return {ok:true,message:'ส่งรายงานให้ลูกค้าจำลองแล้ว'};}return no('เลือกขั้นตอนที่พร้อมใช้งาน');}
