function malwareTimeline(startedAt,stoppedAt,now){if(!startedAt)return {phase:'clean',outbound:false,leaked:false,stopped:false};const stop=Number.isFinite(stoppedAt)&&stoppedAt>0?stoppedAt:Infinity,elapsed=Math.max(0,now-startedAt),outbound=elapsed>=20000&&stop>=startedAt+20000,leaked=elapsed>=45000&&stop>=startedAt+45000;return {phase:leaked?'leaked':stop!==Infinity?'contained':outbound?'outbound':'active',outbound,leaked,stopped:stop!==Infinity};}
